'use client';
import { type ReactNode, useRef, useState } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={transition}
    >
      {children}
    </MotionComponent>
  );
}

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { InView } from "@/components/primitives/in-view"
import { SectionHead, SectionShell } from "@/components/primitives/handcraft"
import { cn } from "@/lib/utils"

// The layer components — each one is its own import, exactly like the
// sandwich logic: bun, lettuce, tomato, cheese, patty, base.
import { BunTop } from "./layers/BunTop"
import { Lettuce } from "./layers/Lettuce"
import { Tomato } from "./layers/Tomato"
import { Cheese } from "./layers/Cheese"
import { Patty } from "./layers/Patty"
import { BunBottom } from "./layers/BunBottom"

// ═══ JOB         Prove the layer architecture with a stack you can edit.
// ═══ EMOTION     Playful control — building your own order.
// ═══ SIGNATURE   Every ingredient is a separate component; toggling a chip
//                 springs the layer in or out of the physical stack, and the
//                 whole thing re-settles like a real sandwich being rebuilt.

export type BurgerLayerId = "bunTop" | "lettuce" | "tomato" | "cheese" | "patty" | "bunBottom"

export type StackBurgerProps = {
  eyebrow?: string
  title?: React.ReactNode
  subtitle?: React.ReactNode
  /** Ingredient layers present on mount, top of stack first. */
  initialLayers?: BurgerLayerId[]
  /** Fixed width of the stack in px (max 360). */
  width?: number
  caption?: string
  tone?: "paper" | "ink"
  className?: string
}

const LAYERS: Record<BurgerLayerId, { label: string; node: () => React.ReactNode }> = {
  bunTop: { label: "Bun top", node: () => <BunTop /> },
  lettuce: { label: "Lettuce", node: () => <Lettuce /> },
  tomato: { label: "Tomato", node: () => <Tomato /> },
  cheese: { label: "Cheese", node: () => <Cheese /> },
  patty: { label: "Patty", node: () => <Patty /> },
  bunBottom: { label: "Bun base", node: () => <BunBottom /> },
}

const STACK_ORDER: BurgerLayerId[] = ["bunTop", "lettuce", "tomato", "cheese", "patty", "bunBottom"]

export function StackBurger({
  eyebrow = "STACK · BURGER",
  title = "Every layer is a component.",
  subtitle = "Toggle the ingredients — each one is its own import, and the stack springs back into shape. Bun, lettuce, tomato, cheese, patty, base: six components, one sandwich.",
  initialLayers = ["bunTop", "lettuce", "tomato", "cheese", "patty", "bunBottom"],
  width = 300,
  caption = "SIX COMPONENTS · ONE STACK",
  tone = "paper",
  className,
}: StackBurgerProps) {
  const ink = tone === "ink"
  const reduce = useReducedMotion()
  const [active, setActive] = React.useState<BurgerLayerId[]>(initialLayers)

  const toggle = (id: BurgerLayerId) =>
    setActive((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]))

  const visible = STACK_ORDER.filter((id) => active.includes(id))
  const hair = ink ? "border-background/15" : "border-border"

  return (
    <SectionShell tone={tone} width={920} rule="bottom" className={className}>
      <InView
        once
        variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      >
        <SectionHead eyebrow={eyebrow} title={title} subtitle={subtitle} tone={tone} />
      </InView>

      <InView
        once
        variants={{ hidden: { opacity: 0, y: 24 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1], delay: 0.1 }}
      >
        <figure className="mt-10">
          {/* ── The stack ── */}
          <div className="flex justify-center">
            <motion.div
              layout={!reduce}
              role="img"
              aria-label={`Burger stack with ${visible.map((id) => LAYERS[id].label.toLowerCase()).join(", ") || "nothing"}`}
              className="relative drop-shadow-[0_28px_24px_hsl(var(--foreground)/0.18)]"
              style={{ width: Math.min(width, 360) }}
            >
              <AnimatePresence initial={false} mode="popLayout">
                {visible.map((id, i) => (
                  <motion.div
                    layout={!reduce}
                    key={id}
                    initial={reduce ? { opacity: 0 } : { opacity: 0, y: -46, scale: 1.06 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={reduce ? { opacity: 0 } : { opacity: 0, y: -30, scale: 0.94 }}
                    transition={{ type: "spring", stiffness: 320, damping: 24, delay: reduce ? 0 : i * 0.03 }}
                    className="relative z-[1]"
                  >
                    {LAYERS[id].node()}
                  </motion.div>
                ))}
              </AnimatePresence>
              {visible.length === 0 && (
                <p className={cn("grid h-24 place-items-center rounded-xl border border-dashed font-mono text-[11px] uppercase tracking-[0.2em]", ink ? "border-background/25 text-background/50" : "border-border text-muted-foreground")}>
                  an empty plate
                </p>
              )}
            </motion.div>
          </div>

          {/* ── Ingredient chips ── */}
          <div className="mt-9 flex flex-wrap items-center justify-center gap-2" role="group" aria-label="Ingredients">
            {STACK_ORDER.map((id) => {
              const on = active.includes(id)
              return (
                <button
                  key={id}
                  type="button"
                  aria-pressed={on}
                  onClick={() => toggle(id)}
                  className={cn(
                    "h-8 rounded-full border px-3.5 font-mono text-[10px] font-bold uppercase tracking-[0.14em] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    on
                      ? ink
                        ? "border-background bg-background text-foreground"
                        : "border-foreground bg-foreground text-background"
                      : ink
                        ? "border-background/25 text-background/60 hover:border-background/50"
                        : "border-border text-muted-foreground hover:border-muted-foreground/60",
                  )}
                >
                  {LAYERS[id].label}
                </button>
              )
            })}
          </div>

          {caption && (
            <figcaption
              className={cn(
                "mt-8 flex items-center justify-between border-t pt-3 font-mono text-[10px] font-bold uppercase tracking-[0.3em]",
                hair,
                ink ? "text-background/55" : "text-muted-foreground",
              )}
            >
              <span>{caption}</span>
              <span aria-hidden className="tabular-nums">{String(active.length).padStart(2, "0")} / 06</span>
            </figcaption>
          )}
        </figure>
      </InView>
    </SectionShell>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── BUN BOTTOM — the base. Flat, slightly tapered, holds everything. ────────

export type BunBottomProps = {
  label?: string
  className?: string
}

export function BunBottom({ label = "Toasted base", className }: BunBottomProps) {
  return (
    <div className={cn("relative h-8 w-full", className)} title={label}>
      <div className="absolute inset-x-1.5 top-0 h-7 rounded-b-[20px] rounded-t-[6px] bg-[#e0a350] shadow-[inset_0_5px_0_0_#c9883a]" />
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── BUN TOP — the upper bun. Owns the dome silhouette. ─────────────────────
// Ingredient colors are CONTENT data (like product swatches), deliberately
// fixed — the lettuce is green in every theme; the layout stays token-driven.

export type BunTopProps = {
  label?: string
  className?: string
}

export function BunTop({ label = "Sesame brioche", className }: BunTopProps) {
  return (
    <div className={cn("relative h-11 w-full", className)} title={label}>
      <div className="absolute inset-x-1 top-0 h-[38px] rounded-t-[48px] rounded-b-[10px] bg-[#e0a350] shadow-[inset_0_-6px_0_0_#c9883a]" />
      {/* sesame */}
      {[
        "left-[16%] top-[9px] -rotate-12", "left-[30%] top-[5px] rotate-6", "left-[45%] top-[8px] -rotate-3",
        "left-[60%] top-[5px] rotate-12", "left-[74%] top-[9px] -rotate-6", "left-[86%] top-[13px] rotate-3",
      ].map((pos) => (
        <span key={pos} className={cn("absolute h-[7px] w-[11px] rounded-[50%] bg-[#f6dca4]", pos)} />
      ))}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── CHEESE — the melt. A band whose corners droop over the layer below. ─────

export type CheeseProps = {
  label?: string
  className?: string
}

export function Cheese({ label = "Melted cheddar", className }: CheeseProps) {
  return (
    <div className={cn("relative h-6 w-full", className)} title={label}>
      <div
        className="absolute inset-x-1 top-0 h-3 rounded-[4px] bg-[#f0b429]"
        style={{ clipPath: "polygon(0 0, 100% 0, 100% 55%, 92% 100%, 84% 55%, 72% 100%, 60% 55%, 48% 100%, 36% 55%, 24% 100%, 12% 55%, 4% 100%, 0 55%)" }}
      />
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── LETTUCE — the ruffle. A wavy band that reads as one leaf. ───────────────

export type LettuceProps = {
  label?: string
  className?: string
}

export function Lettuce({ label = "Crisp lettuce", className }: LettuceProps) {
  return (
    <div className={cn("relative h-5 w-full", className)} title={label}>
      <svg viewBox="0 0 400 20" preserveAspectRatio="none" className="h-full w-full" aria-hidden>
        <path
          d="M0 8 Q 12 2 25 8 T 50 8 T 75 8 T 100 8 T 125 8 T 150 8 T 175 8 T 200 8 T 225 8 T 250 8 T 275 8 T 300 8 T 325 8 T 350 8 T 375 8 T 400 8 L 400 14 Q 388 20 375 14 T 350 14 T 325 14 T 300 14 T 275 14 T 250 14 T 225 14 T 200 14 T 175 14 T 150 14 T 125 14 T 100 14 T 75 14 T 50 14 T 25 14 T 0 14 Z"
          fill="#5fae4e"
        />
      </svg>
    </div>
